export type Entry = { hash: string; size: number; mtime: number; kind: string; [key: string]: unknown };
export type Head = { version: number; vaultId: string; snapshotId: string; parentSnapshotId: string | null;
  deviceId: string; createdAt: number; files: Record<string, Entry>; [key: string]: unknown };
